if ($input.all().length === 0) return [{ json: { cubierto: false } }];
if ($input.all().length === 1) {
  const row = $input.first().json;
  return [{ json: { cubierto: true, ciudad_oficial: row.ciudad, acepta_contraentrega: row.acepta_contraentrega } }];
}
return [{ json: { opciones: $input.all().map(i => i.json) } }];
